function note(state,idx,item,label='Aufgabe'){const tries=Number(state.tries?.[idx]||0),review=Number(state.review?.[idx]||0);if(review===2)return`<div class="sp-t4u-note hint">Richtig korrigiert. ${label} kommt noch einmal.</div>`;if(tries===1)return'<div class="sp-t4u-note bad">Noch nicht richtig.</div>';if(tries===2)return `<div class="sp-t4u-note hint">${esc(item?.hint||'Prüfe die Information noch einmal.')}</div>`;if(tries>=3){const a=Array.isArray(item?.answer)?item.answer[0]:item?.answer;return `<div class="sp-t4u-note hint">Lösung: <strong>${esc(a)}</strong>.</div>`}return''}
